-- DUNGEONSLASHER(AU)[32+64]-V16.01
-- Do not edit this file. Any change breaks the decoder.
local _rfvcrw = 50
local _nxxfbp = 125
local _ihiqmx = 171
local _thlmck = ""

local _gbsvra = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _xkwubl(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _fklkra(d)
	d = d:gsub("[^" .. _gbsvra .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_gbsvra:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _xneqmt = _fklkra(_thlmck)
local _frgzqn = { _rfvcrw, _nxxfbp, _ihiqmx }
local _fwjgmg = {}
for i = 1, #_xneqmt do
	_fwjgmg[i] = string.char(_xkwubl(_xneqmt:byte(i), _frgzqn[(i - 1) % 3 + 1]))
end

local _tahiyo = load or loadstring
local _qsmisi, _bphsrc = _tahiyo(table.concat(_fwjgmg), "=w")
if not _qsmisi then
	gg.alert("Corrupted file: " .. tostring(_bphsrc))
	os.exit()
end
_qsmisi()
